from importlib.metadata import entry_points

class ProviderRegistry:
    def discover(self):
        return entry_points(group='multi_model_harness.providers')

    def load(self, name: str):
        plugins = {ep.name: ep for ep in self.discover()}
        if name not in plugins:
            raise KeyError(f'Unknown provider plugin: {name}')
        return plugins[name].load()()

class SyntheticBenchmarkGenerator:
    async def generate(self, spec, count: int):
        candidates = await self._generate_candidates(spec, count)
        return self._validate_and_deduplicate(candidates)

import hashlib

def fingerprint(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

class JudgeEnsemble:
    async def evaluate(self, item, judges):
        results = [await judge.evaluate(item) for judge in judges]
        return self._aggregate(results)

class ReplayService:
    async def replay(self, manifest):
        return await self._runner.run(manifest.to_run_config())

class Coordinator:
    async def lease(self, worker_id, limit=1):
        return await self._queue.lease(worker_id=worker_id, limit=limit)

class Worker:
    async def run_forever(self):
        while not self._cancelled:
            jobs = await self._coordinator.lease(self.worker_id)
            await self._execute_batch(jobs)

