class PolicyEngine:
    def authorize(self, principal, action, resource):
        decision = self._evaluate(principal, action, resource)
        if not decision.allowed:
            raise PermissionError(decision.reason)

class AuditStore:
    def append(self, event):
        event.previous_hash = self._last_hash()
        event.hash = event.compute_hash()
        self._persist(event)

class Router:
    def choose(self, candidates, constraints):
        qualified = [c for c in candidates if constraints.accepts(c)]
        return min(qualified, key=lambda c: (c.cost, c.latency_ms))

class PromptOptimizer:
    async def optimize(self, prompt, evaluator, budget):
        best = prompt
        for candidate in self._mutations(prompt, budget):
            if await evaluator.score(candidate) > await evaluator.score(best):
                best = candidate
        return best

